    const product = rawHref ? [...byRoute.values()].find((item) => item.route.endsWith(`/products/${rawHref}/`)) : null;
    if (!product) return cardHtml;
    let result = cardHtml.replace(/(data-search=")[^"]*/i, `$1${escape([product.title, product.sku, ...product.pills].join(' ').toLowerCase())}`)
